// One item per new A2 request (reminders send no video), and per AUTO row: an A2 already approved
// by the storyboard's Render final (D-076), sent for information with no buttons. The worker serves the preview against the
// qa_preview job's media token (D-057). Replace the base URL on import.
// The video's own worker (D-074); WORKER is the fallback filled in on deploy.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => ['REQUEST', 'AUTO'].includes(item.json.kind) && item.json.media);
return rows.map(({ json: row }) => {
  const media = typeof row.media === 'string' ? JSON.parse(row.media) : row.media;
  const shortId = String(row.video_id).slice(0, 8);
  return {
    json: {
      url: `${row.worker_url || WORKER}/media/${row.video_id}/${row.version}/${media.job_id}/preview.mp4?t=${media.token}`,
      caption: `👀 #${shortId} v${row.version} · preview 720p${
        row.kind === 'AUTO' ? ' · ✔️ tự duyệt (Render final): đang render bản cuối 1080p' : ''
      }`,
    },
  };
});

// One message with buttons per row from preview_approvals_due(), after its video (Vietnamese,
// D-061); QA check names come from the worker in English and are translated here. Only checks that
// did not pass are listed. Notes come back as a reply to this message (WF-06 finds the request by
// the hidden ref link). Callback data: a2:<A|R>:<32-hex token>.
// Shared Telegram formatting (same in every approval message node): the text goes out as HTML,
// times in Vietnam time (UTC+7, no daylight saving), and the request token rides in a hidden link
// at the start, so a reply to the message finds its request (WF-06) without showing the token.
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const hiddenRef = (kind, token) => `<a href="https://t.me/?${kind}=${token}">\u200d</a>`;
const CHECKS = {
  format: 'định dạng',
  size: 'kích thước',
  duration: 'thời lượng',
  loudness: 'âm lượng',
  subtitles: 'phụ đề',
  'black frames': 'khung hình đen',
  silence: 'im lặng',
};
// AUTO rows (D-076) were approved already: only their video is sent.
const rows = $input.all().filter((item) => typeof item.json.token === 'string' && item.json.kind !== 'AUTO');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, '0')}`;
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const reminder = row.kind === 'REMINDER';
  const media = parse(row.media);
  const cost = Object.entries(parse(row.cost) ?? {})
    .map(([currency, total]) => `${Math.round(total * 100) / 100} ${currency}`)
    .join(', ');
  const length = media?.duration_seconds ? ` · ${clock(media.duration_seconds)}` : '';
  const qa = media
    ? [
        `QA ${esc(media.level)}${reminder ? '' : ` · chi phí ${esc(cost || 'chưa ghi nhận')}`}`,
        ...(media.checks ?? [])
          .filter((check) => check.level !== 'PASS')
          .map((check) => `⚠️ ${esc(CHECKS[check.name] ?? check.name)}: ${esc(check.detail)}`),
      ]
    : [];
  const html = [
    `${hiddenRef('ref', row.token)}<b>${reminder ? '⏰ Nhắc: ' : ''}👀 Duyệt preview</b> · bước 4/5 · A2`,
    `«${esc(row.title ?? '?')}»`,
    `#${shortId} v${row.version} · vòng ${row.round}/4${length}`,
    ...qa,
    'Duyệt → render bản cuối 1080p',
    `⏰ Hạn ${vnTime(row.expires_at)} · ↩️ Reply để góp ý (thành vòng storyboard mới)`,
  ].join('\n');
  return { json: { html, approve: `a2:A:${row.token}`, reject: `a2:R:${row.token}` } };
});
